/* 删除屏幕根对象会递归删除其子控件；活动屏幕的安全切换由辅助函数处理。 */
void ui_menu_screen_destroy(void)
{
    if (aidogui_ui.menu.root != NULL) {
        _ui_screen_destroy(&aidogui_ui.menu.root);
        aidogui_ui.menu.root = NULL;
    }
}

/* 仅用于已离开的屏幕：保留根对象，子控件的 DELETE 回调会清空各自句柄。 */
void ui_menu_screen_clean(void)
{
    if (aidogui_ui.menu.root == NULL || !lv_obj_is_valid(aidogui_ui.menu.root)) return;
    ui_menu_content_ready = false;
    ui_menu_cleaning = true;
    lv_obj_clean(aidogui_ui.menu.root);
    ui_menu_cleaning = false;
}

